// A single-line comment
Console.WriteLine("One statement");

/* A comment that
   spans two lines */
Console.WriteLine(
    "A statement split across lines");

int age = 30;
double height = 1.72;
bool isStudent = false;
char initial = 'G';
string name = "Grace";

Console.WriteLine($"{name} ({initial}) is {age}, {height} m tall. Student: {isStudent}");

age = 31;              // reassigning is fine
Console.WriteLine(age);

var city = "Lisbon";          // inferred as string
var population = 548_000;     // inferred as int
const int DaysInWeek = 7;

population += 1_000;
Console.WriteLine($"{city} has about {population} residents.");
Console.WriteLine($"Two weeks are {DaysInWeek * 2} days.");

// city = 42;         would not compile: cannot convert int to string
// DaysInWeek = 8;    would not compile: a const cannot be assigned

string first = "Ada";
string last = "Lovelace";
double balance = 1234.5;

string full = first + " " + last;
Console.WriteLine(full);
Console.WriteLine($"{first} has {full.Length} characters in her full name.");
Console.WriteLine($"Balance: {balance:F2}");
Console.WriteLine($"Upper: {first.ToUpper()}, starts with A: {first.StartsWith("A")}");

int apples = 7;
int people = 2;

Console.WriteLine(apples / people);            // integer division
Console.WriteLine(apples % people);            // remainder
Console.WriteLine(apples / (double)people);    // real division
Console.WriteLine(10 / 4 * 4);                 // left to right: (10 / 4) * 4

int counter = 5;
counter++;
counter += 10;
Console.WriteLine(counter);
Console.WriteLine(Math.Max(3, 9) + Math.Sqrt(16));

Console.Write("How many tickets? ");
string input = Console.ReadLine() ?? "0";
int tickets = int.Parse(input);
decimal price = 12.50m;

Console.WriteLine($"{tickets} tickets cost {tickets * price:F2}");

